package com.example.demo;

import java.nio.file.*;
import java.nio.file.attribute.FileAttribute;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Enumeration;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class SafeFileReader {

    private static final Path UPLOAD_DIR = Paths.get("/tmp/uploads");

    /**
     * 안전한 파일 처리: 경로 누출 방지, 권한 상승 방지,
     * ZIP 슬립(ZIP Slip) 방지, SHA-256 검증 포함.
     * @param filePath 사용자 입력 파일 경로
     */
    public static String readFile(String filePath) throws IOException {
        Path path = Paths.get(filePath);
        if (!path.startsWith(UPLOAD_DIR)) {
            throw new IllegalArgumentException("경로가 허용된 디렉터리 밖입니다: " + path);
        }
        if (!Files.isReadable(path)) {
            throw new AccessDeniedException("읽기 권한 없음: " + path);
        }
        return Files.readString(path, StandardCharsets.UTF_8);
    }

    public static void processZipFile(String zipPath) throws IOException {
        Path zip = Paths.get(zipPath);
        if (!zip.startsWith(UPLOAD_DIR)) {
            throw new IllegalArgumentException("경로가 허용된 디렉터리 밖입니다: " + zip);
        }
        try (ZipFile zf = new ZipFile(zip)) {
            Enumeration<? extends ZipEntry> entries = zf.entries();
            while (entries.hasMoreElements()) {
                ZipEntry entry = entries.nextElement();
                Path dest = UPLOAD_DIR.resolve(entry.getName());
                if (!dest.startsWith(UPLOAD_DIR)) {
                    throw new IllegalArgumentException("ZIP 슬립 방지 실패: " + entry.getName());
                }
                Files.copy(zf.getInputStream(entry), dest,
                        StandardCopyOption.REPLACE_EXISTING);
            }
        }
    }
}
